const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

document.getElementById('spine').innerHTML='SPINE: <b>'+D.spine.join('</b> &rarr; <b>')+'</b>';
const C=D.counts;
